ode\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/3/5/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/3/5/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/3/5/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/3/\",\"title\":\"Chapter Three: Karma-yoga\"}],\"url_path\":\"/en/library/bg/3/5/\",\"bb\":893,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/3/4/\",\"title\":\"TEXT 4\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/3/6/\",\"title\":\"TEXT 6\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":998,\"bb\":568000,\"url_path\":\"/en/library/bg/3/5/devanagari/\",\"body_final\":\"न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत् ।
कार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः ॥ ५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":999,\"bb\":894,\"url_path\":\"/en/library/bg/3/5/b894/\",\"body_value\":\"na hi kaścit kṣaṇam api
jātu tiṣṭhaty akarma-kṛt
kāryate hy avaśaḥ karma
sarvaḥ prakṛti-jair guṇaiḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1000,\"bb\":895,\"url_path\":\"/en/library/bg/3/5/b895/\",\"shadow_value\":\"na – nor; hi – certainly; kaścit – anyone; kṣaṇam – a moment; api – also; jātu – at any time; tiṣṭhati – remains; akarma-kṛt – without doing something; kāryate – is forced to do; hi – certainly; avaśaḥ – helplessly; karma – work; sarvaḥ – all; prakṛti-jaiḥ – born of the modes of material nature; guṇaiḥ – by the qualities.\",\"word_for_word_value\":[{\"word\":\"na\",\"translation\":\"nor\"},{\"word\":\"hi\",\"translation\":\"certainly\"},{\"word\":\"kaścit\",\"translation\":\"anyone\"},{\"word\":\"kṣaṇam\",\"translation\":\"a moment\"},{\"word\":\"api\",\"translation\":\"also\"},{\"word\":\"jātu\",\"translation\":\"at any time\"},{\"word\":\"tiṣṭhati\",\"translation\":\"remains\"},{\"word\":\"akarma-kṛt\",\"translation\":\"without doing something\"},{\"word\":\"kāryate\",\"translation\":\"is forced to do\"},{\"word\":\"hi\",\"translation\":\"certainly\"},{\"word\":\"avaśaḥ\",\"translation\":\"helplessly\"},{\"word\":\"karma\",\"translation\":\"work\"},{\"word\":\"sarvaḥ\",\"translation\":\"all\"},{\"word\":\"prakṛti-jaiḥ\",\"translation\":\"born of the modes of material nature\"},{\"word\":\"guṇaiḥ\",\"translation\":\"by the qualities\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1001,\"bb\":896,\"url_path\":\"/en/library/bg/3/5/b896/\",\"body_value\":\"Everyone is forced to act helplessly according to the qualities he has acquired from the modes of material nature; therefore no one can refrain from doing something, not even for a moment.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1002,\"bb\":897,\"url_path\":\"/en/library/bg/3/5/b897/\",\"body_value\":\"It is not a question of embodied life, but it is the nature of the soul to be always active. Without the presence of the spirit soul, the material body cannot move. The body is only a dead vehicle to be worked by the spirit soul, which is always active and cannot stop even for a moment. As such, the spirit soul has to be engaged in the good work of Kṛṣṇa consciousness, otherwise it will be engaged in occupations dictated by the illusory energy. In contact with material energy, the spirit soul acquires material modes, and to purify the soul from such affinities it is necessary to engage in the prescribed duties enjoined in the śāstras. But if the soul is engaged in his natural function of Kṛṣṇa consciousness, whatever he is able to do is good for him. The Śrīmad-Bhāgavatam (1.5.17) affirms this:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1003,\"bb\":898,\"url_path\":\"/en/library/bg/3/5/b898/\",\"body_value\":\"tyaktvā sva-dharmaṁ caraṇāmbujaṁ harer
bhajann apakvo ’tha patet tato yadi
yatra kva vābhadram abhūd amuṣya kiṁ
ko vārtha āpto ’bhajatāṁ sva-dharmataḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1004,\"bb\":899,\"url_path\":\"/en/library/bg/3/5/b899/\",\"body_value\":\"“If someone takes to Kṛṣṇa consciousness, even though he may not follow the prescribed duties in the śāstras or execute the devotional service properly, and even though he may fall down from the standard, there is no loss or evil for him. But if he carries out all the injunctions for purification in the śāstras, what does it avail him if he is not Kṛṣṇa conscious?” So the purificatory process is necessary for reaching this point of Kṛṣṇa consciousness. Therefore, sannyāsa, or any purificatory process, is to help reach the ultimate goal of becoming Kṛṣṇa conscious, without which everything is considered a failure.\"}]}],\"short_title\":\"Bg. 3.5\",\"medium_title\":\"Bhagavad-gītā As It Is 3.5\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-